public sealed class OrderService
{
    public async IAsyncEnumerable<OrderDto> StreamAsync(CancellationToken ct) // C# 8
    {
        await foreach (var page in _repo.PagesAsync(ct))
            foreach (var o in page)
                yield return new OrderDto(o.Id, o.Sku);
    }
}

